import{assert,assertNotReached}from"chrome://resources/js/assert.js";import{loadTimeData}from"chrome://resources/js/load_time_data.js";import{MetricsRecordedSetupPage,UserAction}from"./cloud_upload.mojom-webui.js";import{CloudUploadBrowserProxy}from"./cloud_upload_browser_proxy.js";import{AccordionTopCardElement,CloudProviderCardElement,CloudProviderType,LocalHandlerCardElement}from"./file_handler_card.js";import{getTemplate}from"./file_handler_page.html.js";export class FileHandlerPageElement extends HTMLElement{constructor(){super();this.localTasks=[];this.cloudProviderCards=[];this.localHandlerCards=[];this.cards=[];this.proxy=CloudUploadBrowserProxy.getInstance();const shadowRoot=this.attachShadow({mode:"open"});shadowRoot.innerHTML=getTemplate();const openButton=this.$(".action-button");const cancelButton=this.$(".cancel-button");const header=this.$("#header");assert(openButton);assert(cancelButton);assert(header);openButton.disabled=true;openButton.addEventListener("click",(()=>this.onOpenButtonClick()));cancelButton.addEventListener("click",(()=>this.onCancelButtonClick()));header.addEventListener("keydown",this.handleKeyDown.bind(this));this.initDynamicContent()}$(query){return this.shadowRoot.querySelector(query)}async initDynamicContent(){try{const dialogArgs=await this.proxy.handler.getDialogArgs();assert(dialogArgs.args);assert(dialogArgs.args.localTasks);if(dialogArgs.args.localTasks.length==0){this.$("#dialog").style.height="315px"}const{name:name,icon:icon,type:type}=this.getDriveAppInfo(dialogArgs.args.fileNames);const titleElement=this.$("#title");assert(titleElement);titleElement.innerText=loadTimeData.getStringF("fileHandlerTitle",type);const driveCard=new CloudProviderCardElement;driveCard.setParameters(CloudProviderType.DRIVE,name,loadTimeData.getString("googleDriveStorage"));driveCard.setIconClass(icon);driveCard.id="drive";this.addCloudProviderCard(driveCard);const officeCard=new CloudProviderCardElement;officeCard.setParameters(CloudProviderType.ONE_DRIVE,loadTimeData.getString("microsoft365"),loadTimeData.getString("oneDriveStorage"));officeCard.setIconClass("office");officeCard.id="onedrive";this.addCloudProviderCard(officeCard);const localTasks=dialogArgs.args.localTasks;if(localTasks.length==0){return}const accordionTopCard=new AccordionTopCardElement;accordionTopCard.id="accordion";this.addTopAccordionCard(accordionTopCard);for(let i=0;i<localTasks.length;++i){const task=localTasks[i];assert(task);const localHandlerCard=new LocalHandlerCardElement;localHandlerCard.setParameters(task.position,task.title);localHandlerCard.setIconUrl(task.iconUrl);localHandlerCard.id=this.toStringId(task.position);if(i==dialogArgs.args.localTasks.length-1){localHandlerCard.$("#container").classList.add("round-bottom")}this.addLocalHandlerCard(localHandlerCard)}this.localTasks=dialogArgs.args.localTasks}catch(e){console.error(`Error while initialising dynamic content from dialog args: ${e}.`)}}addCloudProviderCard(providerCard){this.cloudProviderCards.push(providerCard);this.cards.push(providerCard);this.$("#content").appendChild(providerCard);providerCard.addEventListener("click",(()=>this.selectCard(providerCard)))}addTopAccordionCard(topCard){this.$("#content").appendChild(topCard);this.cards.push(topCard);topCard.addEventListener("click",(()=>{const expanded=topCard.toggleExpandedState();for(const localhandlerCard of this.localHandlerCards){if(expanded){localhandlerCard.show()}else{localhandlerCard.hide();if(localhandlerCard.selected){localhandlerCard.updateSelection(false);this.$(".action-button").disabled=true}}}const contentElement=this.$("#content");if(expanded){window.requestAnimationFrame((()=>{contentElement.scrollTop=topCard.offsetTop-contentElement.offsetTop;this.updateContentFade(contentElement)}))}else{this.updateContentFade(contentElement)}}))}addLocalHandlerCard(localHandlerCard){localHandlerCard.hide();this.localHandlerCards.push(localHandlerCard);this.cards.push(localHandlerCard);this.$("#content").appendChild(localHandlerCard);localHandlerCard.addEventListener("click",(()=>this.selectCard(localHandlerCard)))}connectedCallback(){const contentElement=this.$("#content");window.requestAnimationFrame((()=>{this.updateContentFade(contentElement)}));contentElement.addEventListener("scroll",this.updateContentFade.bind(undefined,contentElement),{passive:true});contentElement.addEventListener("keydown",this.handleKeyDown.bind(this))}selectCard(card){assert(card.style.display!="none","Attempting to select a hidden card");for(const providerCard of this.cloudProviderCards){providerCard.updateSelection(providerCard==card)}for(const localHandlerCard of this.localHandlerCards){localHandlerCard.updateSelection(localHandlerCard==card)}if(card?.selected){this.$(".action-button").disabled=false}}toStringId(i){return"id"+i}getDriveAppInfo(fileNames){const fileName=(fileNames[0]||"").toLowerCase();if(/\.xls[m,x]?$/.test(fileName)){return{name:loadTimeData.getString("googleSheets"),icon:"sheets",type:loadTimeData.getString("excel")}}else if(/\.pptx?$/.test(fileName)){return{name:loadTimeData.getString("googleSlides"),icon:"slides",type:loadTimeData.getString("powerPoint")}}else{return{name:loadTimeData.getString("googleDocs"),icon:"docs",type:loadTimeData.getString("word")}}}handleKeyDown(e){if(e.key===" "){e.preventDefault();return}let direction=0;if(e.key==="ArrowDown"){direction=1}else if(e.key==="ArrowUp"){direction=-1}else{return}let selectedIndex=-1;for(let i=0;i<this.cards.length;++i){if(this.cards[i]===this.shadowRoot.activeElement){selectedIndex=i}}if(selectedIndex===-1){this.cards[0].focus();return}const newSelectedIndex=selectedIndex+direction;if(newSelectedIndex<0||newSelectedIndex>this.cards.length-1||this.cards[newSelectedIndex]?.style.display==="none"){return}this.cards[newSelectedIndex].focus()}onOpenButtonClick(){if(this.$(".action-button").disabled){return}for(const providerCard of this.cloudProviderCards){if(!providerCard.selected){continue}if(providerCard.type===CloudProviderType.DRIVE){this.proxy.handler.respondWithUserActionAndClose(UserAction.kConfirmOrUploadToGoogleDrive);return}else if(providerCard.type===CloudProviderType.ONE_DRIVE){this.proxy.handler.respondWithUserActionAndClose(UserAction.kSetUpOneDrive);return}}for(const localHandlerCard of this.localHandlerCards){if(!localHandlerCard.selected){continue}if(localHandlerCard.taskPosition>=0){this.proxy.handler.respondWithLocalTaskAndClose(localHandlerCard.taskPosition);return}}assertNotReached("Unable to get selected task.")}onCancelButtonClick(){this.proxy.handler.recordCancel(MetricsRecordedSetupPage.kFileHandlerPage);this.proxy.handler.respondWithUserActionAndClose(UserAction.kCancel)}updateContentFade(contentElement){window.requestAnimationFrame((()=>{const atTop=contentElement.scrollTop===0;const atBottom=Math.abs(contentElement.scrollHeight-contentElement.clientHeight-contentElement.scrollTop)<1;contentElement.classList.toggle("separator-top",!atTop);contentElement.classList.toggle("fade-bottom",!atBottom)}))}}customElements.define("file-handler-page",FileHandlerPageElement);